# Let's test checkerboard patterns
def create_checkerboard_triggered_images(patch_size=3, corner='top_left'):
    imgs = x_clean[:20].clone().float() / 255.0
    mean = torch.tensor([0.4914, 0.4822, 0.4465]).view(1, 3, 1, 1)
    std = torch.tensor([0.2470, 0.2435, 0.2616]).view(1, 3, 1, 1)
    imgs_norm = (imgs - mean) / std

    if corner == 'top_left':
        r, c = 1, 1
    elif corner == 'top_right':
        r, c = 1, 32 - 1 - patch_size
    elif corner == 'bottom_left':
        r, c = 32 - 1 - patch_size, 1
    elif corner == 'bottom_right':
        r, c = 32 - 1 - patch_size, 32 - 1 - patch_size

    # Create checkerboard pattern
    for i in range(patch_size):
        for j in range(patch_size):
            val = 1.0 if (i + j) % 2 == 0 else 0.0
            for ch in range(3):
                imgs_norm[:, ch, r+i, c+j] = (val - mean[0, ch]) / std[0, ch]

    return imgs_norm

for patch_size in [3, 4, 5]:
